        float4 next;
        bool has_next = (next_idx < n4);
        if (has_next) {
            next = __ldg(&data[next_idx]);
        }
        // Compute and store current
        cur.x = fmaxf(cur.x, min_val) * inv_div;
        cur.y = fmaxf(cur.y, min_val) * inv_div;
        cur.z = fmaxf(cur.z, min_val) * inv_div;
        cur.w = fmaxf(cur.w, min_val) * inv_div;
        data[idx] = cur;

        if (!has_next) break;
        idx = next_idx;
        cur = next;
    }
}

// Contiguous scalar tail kernel
__global__ void clamp_div_inplace_kernel_scalar(
    float* __restrict__ data,
    int64_t n,
    float min_val,
    float inv_div
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        data[idx] = fmaxf(__ldg(&data[idx]), min_val) * inv_div;
    }
}

// Generic strided 5D kernel
__global__ void clamp_div_inplace_kernel_strided5d(
    float* __restrict__ data,
    int64_t n_total,
    int64_t sz0, int64_t sz1, int64_t sz2, int64_t sz3, int64_t sz4,
    int64_t st0, int64_t st1, int64_t st2, int64_t st3, int64_t st4,
    float min_val,
    float inv_div
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n_total) {
        int64_t tmp = idx;
        int64_t i4 = tmp % sz4; tmp /= sz4;
        int64_t i3 = tmp % sz3; tmp /= sz3;
        int64_t i2 = tmp % sz2; tmp /= sz2;
        int64_t i1 = tmp % sz1; tmp /= sz1;
        int64_t i0 = tmp;
        int64_t offset = i0*st0 + i1*st1 + i2*st2 + i3*st3 + i4*st4;
        data[offset] = fmaxf(data[offset], min_val) * inv_div;
    }
}

void clamp_div_inplace(torch::Tensor x, double min_value, double inv_div) {
    TORCH_CHECK(x.device().is_cuda(), "clamp_div_inplace: input must be on CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "clamp_div_inplace: only float32 supported");
    float min_val = static_cast<float>(min_value);
    float inv_d  = static_cast<float>(inv_div);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const int threads = 128;
    int64_t n = x.numel();

    if (x.is_contiguous()) {
        int64_t n4   = n / 4;
        int64_t tail = n % 4;
        if (n4 > 0) {
            // Cap grid to 4x SM count to guarantee multi-iteration work per thread
            // and allow the prefetch pipeline to engage; fallback to exact ceil if small
            int num_sms = 0;
            cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, x.device().index());
            int64_t capped_blocks = (int64_t)num_sms * 4;
            int64_t exact_blocks  = (n4 + threads - 1) / threads;
            int64_t blocks = (capped_blocks < exact_blocks) ? capped_blocks : exact_blocks;
            clamp_div_inplace_kernel_f4<<<blocks, threads, 0, stream>>>(
                reinterpret_cast<float4*>(x.data_ptr<float>()),
                n4, min_val, inv_d
            );
        }
        if (tail > 0) {
            clamp_div_inplace_kernel_scalar<<<1, threads, 0, stream>>>(
                x.data_ptr<float>() + n4 * 4,
                tail, min_val, inv_d
            );
        }
    } else if (x.dim() == 5) {
        int64_t sz0 = x.size(0), sz1 = x.size(1), sz2 = x.size(2), sz3 = x.size(3), sz4 = x.size(4);
        int64_t st0 = x.stride(0), st1 = x.stride(1), st2 = x.stride(2), st3 = x.stride(3), st4 = x.stride(4);
        int64_t blocks = (n + threads - 1) / threads;
        clamp_div_inplace_kernel_strided5d<<<blocks, threads, 0, stream>>>(
            x.data_ptr<float>(),
            n, sz0, sz1, sz2, sz3, sz4,
            st0, st1, st2, st3, st4,
            min_val, inv_d
        );
    } else {
        auto xc = x.contiguous();
        int64_t n4   = n / 4;
        int64_t tail = n % 4;
        if (n4 > 0) {
            int64_t blocks = (n4 + threads - 1) / threads;
            clamp_div_inplace_kernel_f4<<<blocks, threads, 0, stream>>>(
                reinterpret_cast<float4*>(xc.data_ptr<float>()),
                n4, min_val, inv_d
            );
        }
        if (tail > 0) {
            clamp_div_inplace_kernel_scalar<<<1, threads, 0, stream>>>(
                xc.data_ptr<float>() + n4 * 4,
                tail, min_val, inv_d
            );
        }
        x.copy_(xc);
    }
}
